package com.collabspace.dto; import jakarta.validation.constraints.*; public final class AuthDtos { private AuthDtos(){} public record RegisterRequest(@NotBlank @Size(min=3,max=40) String username,@NotBlank @Email String email,@NotBlank @Size(min=8,max=100) String password){} public record LoginRequest(@NotBlank String email,@NotBlank String password){} public record AuthResponse(String token,UserResponse user){} public record UserResponse(java.util.UUID id,String username,String email,String profilePicture,String status,java.time.Instant lastSeen,String role){} }